  from jsonb_to_recordset($fqjson$[{"id":"common","name":"Common Box","name_zh":"普通盲盒","cost":50,"sort":1,"description":"Everyday cuties from the starter collection.","description_zh":"日常可爱单品。","odds":{"Common":75,"Rare":20,"Epic":5},"duplicate_refund":{"Common":10,"Rare":20,"Epic":40,"Legendary":80}},{"id":"rare","name":"Rare Box","name_zh":"稀有盲盒","cost":100,"sort":2,"description":"Better odds for Rare and Epic pieces, with a small Legendary chance.","description_zh":"更高几率获得稀有与史诗单品。","odds":{"Common":40,"Rare":45,"Epic":12,"Legendary":3},"duplicate_refund":{"Common":10,"Rare":20,"Epic":40,"Legendary":80}},{"id":"premium","name":"Premium Box","name_zh":"豪华盲盒","cost":200,"sort":3,"description":"No Commons. Rare or better, with the best Legendary odds.","description_zh":"保底稀有，传说几率最高。","odds":{"Rare":55,"Epic":35,"Legendary":10},"duplicate_refund":{"Common":10,"Rare":20,"Epic":40,"Legendary":80}}]$fqjson$::jsonb)
