insert into public.fq_missions (id, title, title_zh, event, target, reward, active)
select x.id, x.title, x.title_zh, x.event, x.target, x.reward, true
  from jsonb_to_recordset($fqjson$[{"id":"m_login","title":"Say hi! Claim your daily login","title_zh":"领取每日登录奖励","event":"daily_login","target":1,"reward":10},{"id":"m_play2","title":"Play any 2 mini-games","title_zh":"玩任意 2 局小游戏","event":"game_finished","target":2,"reward":15},{"id":"m_play4","title":"Play any 4 mini-games","title_zh":"玩任意 4 局小游戏","event":"game_finished","target":4,"reward":25},{"id":"m_trivia3","title":"Answer 3 trivia questions correctly","title_zh":"答对 3 道知识问答","event":"trivia_correct","target":3,"reward":15},{"id":"m_tap","title":"Finish a Quick Tap round","title_zh":"完成一局快速点击","event":"quick_tap_finished","target":1,"reward":10},{"id":"m_memory","title":"Clear a Memory Match board","title_zh":"完成一局记忆翻牌","event":"memory_match_finished","target":1,"reward":10},{"id":"m_style","title":"Save a new look for your avatar","title_zh":"保存一次头像造型","event":"avatar_saved","target":1,"reward":10},{"id":"m_box","title":"Open a blind box","title_zh":"开启一个盲盒","event":"box_opened","target":1,"reward":20},{"id":"m_shop","title":"Buy an item in the shop","title_zh":"在商店购买一件单品","event":"item_bought","target":1,"reward":15},{"id":"m_challenge","title":"Complete today's Daily Challenge","title_zh":"完成今日挑战","event":"challenge_done","target":1,"reward":20}]$fqjson$::jsonb) as x(id text, title text, title_zh text, event text, target integer, reward integer)
