  from jsonb_to_recordset($fqjson$[{"id":"a_first_login","icon":"flower","metric":"logins","target":1,"reward":10,"title":"Hello, Fan Quest!","title_zh":"你好，Fan Quest","description":"Claim your first daily login.","description_zh":"首次领取每日登录。","sort":0},{"id":"a_streak3","icon":"flame","metric":"best_streak","target":3,"reward":20,"title":"Warming up","title_zh":"渐入佳境","description":"Reach a 3-day login streak.","description_zh":"连续登录 3 天。","sort":1},{"id":"a_streak7","icon":"medal","metric":"best_streak","target":7,"reward":50,"title":"Week-long fan","title_zh":"一周铁粉","description":"Reach a 7-day login streak.","description_zh":"连续登录 7 天。","sort":2},{"id":"a_games10","icon":"gamepad","metric":"games_played","target":10,"reward":25,"title":"Game time","title_zh":"游戏时间","description":"Finish 10 mini-games.","description_zh":"完成 10 局小游戏。","sort":3},{"id":"a_games50","icon":"joystick","metric":"games_played","target":50,"reward":80,"title":"Arcade regular","title_zh":"游戏达人","description":"Finish 50 mini-games.","description_zh":"完成 50 局小游戏。","sort":4},{"id":"a_trivia20","icon":"bulb","metric":"trivia_correct","target":20,"reward":40,"title":"Big brain","title_zh":"知识满分","description":"Answer 20 trivia questions correctly.","description_zh":"累计答对 20 题。","sort":5},{"id":"a_box1","icon":"gift","metric":"boxes_opened","target":1,"reward":10,"title":"Surprise!","title_zh":"惊喜！","description":"Open your first blind box.","description_zh":"开启第一个盲盒。","sort":6},{"id":"a_box10","icon":"box","metric":"boxes_opened","target":10,"reward":60,"title":"Box collector","title_zh":"盲盒收藏家","description":"Open 10 blind boxes.","description_zh":"开启 10 个盲盒。","sort":7},{"id":"a_items10","icon":"shirt","metric":"items_owned","target":10,"reward":30,"title":"Wardrobe starter","title_zh":"衣橱初成","description":"Own 10 non-starter items.","description_zh":"拥有 10 件非初始单品。","sort":8},{"id":"a_items30","icon":"hanger","metric":"items_owned","target":30,"reward":100,"title":"Fashion icon","title_zh":"时尚达人","description":"Own 30 non-starter items.","description_zh":"拥有 30 件非初始单品。","sort":9},{"id":"a_legendary","icon":"star","metric":"legendary_owned","target":1,"reward":50,"title":"Legend!","title_zh":"传说降临","description":"Own a Legendary item.","description_zh":"获得一件传说单品。","sort":10},{"id":"a_missions10","icon":"scroll","metric":"missions_claimed","target":10,"reward":40,"title":"Mission accomplished","title_zh":"任务达人","description":"Claim 10 daily missions.","description_zh":"领取 10 次每日任务奖励。","sort":11},{"id":"a_looks3","icon":"camera","metric":"looks_saved","target":3,"reward":15,"title":"Lookbook","title_zh":"造型册","description":"Save 3 outfits to your lookbook.","description_zh":"在造型册保存 3 套造型。","sort":12},{"id":"a_points1000","icon":"gem","metric":"points_earned","target":1000,"reward":100,"title":"Point millionaire","title_zh":"积分大户","description":"Earn 1,000 Fan Points in total.","description_zh":"累计获得 1000 积分。","sort":13}]$fqjson$::jsonb)
