insert into fq_private.trivia (id, level, question, question_zh, choices, choices_zh, answer, active)
select x.id, x.level, x.question, x.question_zh, x.choices, x.choices_zh, x.answer, true
  from jsonb_to_recordset($fqjson$[{"id":1,"level":"easy","question":"Which colour do you get by mixing pink and blue paint?","question_zh":"粉色和蓝色颜料混合会得到什么颜色？","choices":["Purple","Green","Orange","Yellow"],"choices_zh":["紫色","绿色","橙色","黄色"],"answer":0},{"id":2,"level":"easy","question":"What does a blind box guarantee?","question_zh":"盲盒保证什么？","choices":["A specific rare item","A random item from the listed pool","Unlimited points","A refund"],"choices_zh":["指定的稀有物品","列出奖池中的随机物品","无限积分","退款"],"answer":1},{"id":3,"level":"easy","question":"How many days are in a week?","question_zh":"一周有几天？","choices":["5","6","7","8"],"choices_zh":["5","6","7","8"],"answer":2},{"id":4,"level":"easy","question":"Which of these is the safest password habit?","question_zh":"以下哪种密码习惯最安全？","choices":["Reuse one password","Use a unique strong password","Share it with friends","Write it on your screen"],"choices_zh":["所有账号同一个密码","每个账号用独立强密码","分享给朋友","写在屏幕上"],"answer":1},{"id":5,"level":"easy","question":"Fans waving glowing sticks at a concert are holding…","question_zh":"演唱会上粉丝挥舞的发光棒叫什么？","choices":["Lightsticks","Chopsticks","Drumsticks","Glue sticks"],"choices_zh":["应援棒","筷子","鼓槌","胶棒"],"answer":0},{"id":6,"level":"easy","question":"Which animal is known for long ears and hopping?","question_zh":"哪种动物以长耳朵和蹦跳著称？","choices":["Cat","Bunny","Frog","Bear"],"choices_zh":["猫","兔子","青蛙","熊"],"answer":1},{"id":7,"level":"easy","question":"A \"comeback\" in K-pop usually means…","question_zh":"K-pop 中的 \"回归\" 通常指什么？","choices":["A group releases new music","A concert is cancelled","An idol retires","A fan club closes"],"choices_zh":["团体发布新作品","演唱会取消","偶像退役","粉丝团解散"],"answer":0},{"id":8,"level":"easy","question":"What does \"OT\" stand for when fans talk about a full group?","question_zh":"粉丝说 \"OT\" 指整个团体时，它代表什么？","choices":["Overtime","One True","Original / all members together","Online Ticket"],"choices_zh":["加班","唯一真爱","全员到齐","线上票务"],"answer":2},{"id":9,"level":"easy","question":"How many sides does a hexagon have?","question_zh":"六边形有几条边？","choices":["5","6","7","8"],"choices_zh":["5","6","7","8"],"answer":1},{"id":10,"level":"easy","question":"Which planet is known as the Red Planet?","question_zh":"哪颗行星被称为红色星球？","choices":["Venus","Jupiter","Mars","Saturn"],"choices_zh":["金星","木星","火星","土星"],"answer":2},{"id":11,"level":"normal","question":"In a gacha game, what is \"pity\"?","question_zh":"抽卡游戏中的 \"保底\" 是什么？","choices":["A guaranteed reward after many pulls","A free daily item","A refund system","A chat feature"],"choices_zh":["抽满一定次数必得奖励","每日免费物品","退款机制","聊天功能"],"answer":0},{"id":12,"level":"normal","question":"What is a \"bias\" in K-pop fandom?","question_zh":"K-pop 饭圈里的 \"本命\" 指什么？","choices":["Your favourite member","A rival group","A music chart","A dance move"],"choices_zh":["最喜欢的成员","竞争团体","音乐榜单","舞蹈动作"],"answer":0},{"id":13,"level":"normal","question":"What does \"POB\" stand for when buying albums?","question_zh":"买专辑时的 \"POB\" 指什么？","choices":["Pre-order benefit","Photo of band","Point of buying","Post office box"],"choices_zh":["预购特典","乐队照片","购买点","邮政信箱"],"answer":0},{"id":14,"level":"normal","question":"Which shape has every point the same distance from its centre?","question_zh":"哪种图形上每一点到中心距离都相等？","choices":["Square","Triangle","Circle","Oval"],"choices_zh":["正方形","三角形","圆形","椭圆"],"answer":2},{"id":15,"level":"normal","question":"How many minutes is a classic Pomodoro focus session?","question_zh":"经典番茄钟专注一次多少分钟？","choices":["15","25","45","60"],"choices_zh":["15","25","45","60"],"answer":1},{"id":16,"level":"normal","question":"What is the chemical symbol for gold?","question_zh":"金的化学符号是什么？","choices":["Go","Gd","Au","Ag"],"choices_zh":["Go","Gd","Au","Ag"],"answer":2},{"id":17,"level":"normal","question":"Which language is mainly used to style web pages?","question_zh":"主要用来给网页设置样式的语言是？","choices":["HTML","CSS","SQL","Python"],"choices_zh":["HTML","CSS","SQL","Python"],"answer":1},{"id":18,"level":"normal","question":"A \"photocard\" is usually found…","question_zh":"\"小卡\" 通常出现在哪里？","choices":["Inside albums","In train stations","On concert stages","In cookbooks"],"choices_zh":["专辑里","火车站","舞台上","食谱里"],"answer":0},{"id":19,"level":"normal","question":"Which city hosts Singapore's National Stadium?","question_zh":"新加坡国家体育场位于哪个城市？","choices":["Kuala Lumpur","Singapore","Bangkok","Jakarta"],"choices_zh":["吉隆坡","新加坡","曼谷","雅加达"],"answer":1},{"id":20,"level":"normal","question":"What does \"SLAM\" stand for in robotics?","question_zh":"机器人学中的 SLAM 指什么？","choices":["Simultaneous Localization and Mapping","Smart Laser Arm Motor","Sensor Logic and Motion","Single Lidar Area Map"],"choices_zh":["同时定位与建图","智能激光臂电机","传感器逻辑与运动","单激光雷达区域图"],"answer":0},{"id":21,"level":"hard","question":"How many bits are in one byte?","question_zh":"一个字节有多少位？","choices":["4","8","16","32"],"choices_zh":["4","8","16","32"],"answer":1},{"id":22,"level":"hard","question":"Which sorting algorithm has average O(n log n) time and uses a pivot?","question_zh":"哪种排序算法平均 O(n log n) 且使用基准元素？","choices":["Bubble sort","Quicksort","Insertion sort","Selection sort"],"choices_zh":["冒泡排序","快速排序","插入排序","选择排序"],"answer":1},{"id":23,"level":"hard","question":"In a PID controller, what does the \"I\" term respond to?","question_zh":"PID 控制器中 I 项响应什么？","choices":["Current error","Accumulated past error","Rate of change of error","Setpoint only"],"choices_zh":["当前误差","累积误差","误差变化率","仅设定值"],"answer":1},{"id":24,"level":"hard","question":"What is 15% of 240?","question_zh":"240 的 15% 是多少？","choices":["24","30","36","40"],"choices_zh":["24","30","36","40"],"answer":2},{"id":25,"level":"hard","question":"Which gas makes up most of Earth's atmosphere?","question_zh":"地球大气中含量最多的气体是？","choices":["Oxygen","Carbon dioxide","Nitrogen","Argon"],"choices_zh":["氧气","二氧化碳","氮气","氩气"],"answer":2},{"id":26,"level":"hard","question":"What is the binary representation of the number 10?","question_zh":"数字 10 的二进制表示是？","choices":["1010","1001","1100","0110"],"choices_zh":["1010","1001","1100","0110"],"answer":0}]$fqjson$::jsonb)
    as x(id integer, level text, question text, question_zh text, choices jsonb, choices_zh jsonb, answer integer)
on conflict (id) do update set level = excluded.level, question = excluded.question, question_zh = excluded.question_zh,
  choices = excluded.choices, choices_zh = excluded.choices_zh, answer = excluded.answer, active = true;
update fq_private.trivia set active = false where id > 26;

-- Carry over v1 prototype inventory (item keys match v2 item ids).
do $$ begin
  if to_regclass('public.fq_v1_inventory') is not null then
    insert into public.fq_inventory (user_id, item_id, source, acquired_at)
    select v.user_id, v.item_key, 'migration', v.created_at
      from public.fq_v1_inventory v join public.fq_items i on i.id = v.item_key
      join public.fq_profiles p on p.user_id = v.user_id
    on conflict do nothing;
  end if;
end $$;
